use serde::{Deserialize, Serialize};
use std::path::Path;
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum FormatCategory {
    Audio,
    Video,
    Image,
    Document,
    Data,
    Model3D,
    Archive,
    Font,
    Subtitle,
    Unknown,
}
impl FormatCategory {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Audio => "Audio",
            Self::Video => "Video",
            Self::Image => "Image",
            Self::Document => "Document",
            Self::Data => "Data",
            Self::Model3D => "3D Model",
            Self::Archive => "Archive",
            Self::Font => "Font",
            Self::Subtitle => "Subtitle",
            Self::Unknown => "Unknown",
        }
    }
}
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct FormatInfo {
    pub ext: &'static str,
    pub name: &'static str,
    pub category: FormatCategory,
    pub mime: &'static str,
    pub suggested_targets: &'static [&'static str],
}
pub static VIDEO_RESOLUTIONS: &[(&str, &str)] = &[
    ("2160p", "3840x2160"),
    ("1080p", "1920x1080"),
    ("720p", "1280x720"),
    ("480p", "854x480"),
];
pub fn is_video_resolution_target(ext: &str) -> bool {
    let clean = ext.trim_start_matches('.').to_lowercase();
    if let Some(info) = find_format(&clean) {
        if info.category == FormatCategory::Video {
            return true;
        }
    }
    matches!(clean.as_str(), "gif" | "apng")
}
pub fn is_video_source(ext: &str) -> bool {
    let clean = ext.trim_start_matches('.').to_lowercase();
    if let Some(info) = find_format(&clean) {
        return info.category == FormatCategory::Video;
    }
    false
}
pub fn scale_target_for(ext: &str) -> &'static str {
    match ext.trim_start_matches('.').to_lowercase().as_str() {
        "cr2" | "cr3" | "nef" | "arw" | "dng" | "raf" | "orf" | "rw2" | "crw" | "pef" | "srw" | "srf" | "mrw" | "dcr" | "kdc" | "erf" | "mos" | "nrw" | "mef" | "x3f" | "3fr" | "rwl" => "jpg",
        "clip" => "png",
        "cur" => "ico",
        "bik" | "bik2" | "rm" | "rmvb" | "vc1" => "mp4",
        "dnxhd" | "prores" | "mxf" => "mov",
        "3g2" | "3gp" | "3gpp" | "f4v" | "dvr-ms" => "mp4",
        "divx" | "xvid" => "avi",
        _ => {
            if let Some(info) = find_format(ext) {
                return info.ext;
            }
            "png"
        }
    }
}
