pub fn find_format(ext: &str) -> Option<&'static FormatInfo> {
    let clean_ext = ext.trim_start_matches('.').to_lowercase();
    FORMAT_DATABASE.iter().find(|f| f.ext == clean_ext)
}
pub fn detect_format_from_path<P: AsRef<Path>>(path: P) -> Option<&'static FormatInfo> {
    let p = path.as_ref();
    let ext = p.extension()?.to_str()?;
    find_format(ext)
}
pub fn get_suggested_conversions(ext: &str) -> Vec<&'static str> {
    let mut out: Vec<&'static str> = Vec::new();
    if let Some(info) = find_format(ext) {
        out.extend_from_slice(info.suggested_targets);
        if matches!(info.category, FormatCategory::Image | FormatCategory::Video) && info.ext != "gif" && !out.contains(&"gif") {
            out.push("gif");
        }
    }
    out
}
